# Normal spacing in authored prose; preserve literal source evidence and formula strings.
import re

def prose(s):
 s=re.sub(r'(?<=[a-z])(?=\d)',' ',s)
 s=re.sub(r'(?<=[a-z]{2})(?=[(\[])',' ',s)
 s=s.replace('andtan','and tan').replace('Set−','Set −').replace('Solve−','Solve −').replace('and−','and −').replace('for0','for 0').replace('on0','on 0').replace('toπ','to π')
 s=re.sub(r'([,;:])(?=\S)',r'\1 ',s)
 s=re.sub(r'\b(and|or|to|from|with|about|is|of|at|by|the|than|has|costs|scores|gives|obtain|equals|angle|angles|coefficient|denominator|probability|fitness|cost|theta)(?=[(\[0-9θΠ−√])',r'\1 ',s)
 s=re.sub(r'(?<=\d)(?=(?:copies|bits|moves|turns|rows|columns|levels|degrees|radians|ms|s)\b)',' ',s)
 return s
for q in b.questions:
 q['stem']=prose(q['stem']);q['subtopic']=prose(q['subtopic']);q['assumptions']=[prose(s) for s in q['assumptions']]
 for o in q['options']:o['text']=prose(o['text'])
 sol=q['solution']
 for k in ['justification','simpleExplanation']:sol[k]=prose(sol[k])
 for k in ['steps','misconceptions','examTraps']:sol[k]=[prose(s) for s in sol[k]]
 sol['optionExplanations']={k:prose(v) for k,v in sol['optionExplanations'].items()}
 for f in sol['formulas']:
  f['assumptions']=[prose(x) for x in f['assumptions']]
  f['variables']={k:prose(v) for k,v in f['variables'].items()}
  f['units']={k:prose(v) for k,v in f['units'].items()}
 for c in q['citations']:c['locator']=prose(c['locator'])
 if 'conflictResolution' in q:
  for k in ['sourceClaim','basis','method']:q['conflictResolution'][k]=prose(q['conflictResolution'][k])
for c in b.concepts.values():
 for k in ['title','subtopic','description']:c[k]=prose(c[k])
